import pytest
from fastapi.testclient import TestClient

def test_register_user(client: TestClient):
    response = client.post(
        "/register",
        json={"email": "test@example.com", "password": "securepassword123"}
    )
    assert response.status_code == 201
    data = response.json()
    assert data["email"] == "test@example.com"
    assert "id" in data
    assert "password" not in data

def test_register_duplicate_email(client: TestClient):
    client.post(
        "/register",
        json={"email": "test@example.com", "password": "securepassword123"}
    )
    response = client.post(
        "/register",
        json={"email": "test@example.com", "password": "anotherpassword"}
    )
    assert response.status_code == 400
    assert "already registered" in response.json()["detail"]

def test_login_success(client: TestClient):
    client.post(
        "/register",
        json={"email": "test@example.com", "password": "securepassword123"}
    )
    response = client.post(
        "/login",
        data={"username": "test@example.com", "password": "securepassword123"}
    )
    assert response.status_code == 200
    data = response.json()
    assert "access_token" in data
    assert data["token_type"] == "bearer"

def test_login_wrong_password(client: TestClient):
    client.post(
        "/register",
        json={"email": "test@example.com", "password": "securepassword123"}
    )
    response = client.post(
        "/login",
        data={"username": "test@example.com", "password": "wrongpassword"}
    )
    assert response.status_code == 401
    assert "Incorrect email or password" in response.json()["detail"]

def test_login_nonexistent_user(client: TestClient):
    response = client.post(
        "/login",
        data={"username": "nonexistent@example.com", "password": "password"}
    )
    assert response.status_code == 401

def test_access_protected_route_success(client: TestClient):
    client.post(
        "/register",
        json={"email": "test@example.com", "password": "securepassword123"}
    )
    login_response = client.post(
        "/login",
        data={"username": "test@example.com", "password": "securepassword123"}
    )
    token = login_response.json()["access_token"]

    response = client.get(
        "/me",
        headers={"Authorization": f"Bearer {token}"}
    )
    assert response.status_code == 200
    data = response.json()
    assert data["email"] == "test@example.com"

def test_access_protected_route_unauthorized(client: TestClient):
    response = client.get("/me")
    assert response.status_code == 401

def test_logout(client: TestClient):
    client.post(
        "/register",
        json={"email": "test@example.com", "password": "securepassword123"}
    )
    login_response = client.post(
        "/login",
        data={"username": "test@example.com", "password": "securepassword123"}
    )
    token = login_response.json()["access_token"]

    response = client.post(
        "/logout",
        headers={"Authorization": f"Bearer {token}"}
    )
    assert response.status_code == 200
    assert "Successfully logged out" in response.json()["message"]

    # Trying to logout without token should fail 401
    response_unauth = client.post("/logout")
    assert response_unauth.status_code == 401
